// v23.xx (gfx33), HIS ORDER 2026-10-12 (the graphics program, item 14): A RARE DROP SENDS UP A BEAM. A pile whose contents are known
// (gfx32: dropped, or opened with something left) and whose best item is rare or better sends up a soft column of light in its
// rarity colour, 150 units tall, so a good drop reads from across a street the way it does in ARC Raiders. It is drawn after the
// light and BEFORE the fog of war sheet (gfxPreFogE, beside the gfx2 pre-fog hook), in the world transform the air pass records,
// and only for a pile the player can see right now (canSee, the eyes VIS uses), so a beam never shows loot through a wall. Unopened
// boxes never get one (his note of 2026-08-26).
var GFXE={wm:null};
function gfxBeamSpr(r){
  var st=gfxStore('gfxEbeam'), c, x, gr, col=RCOL[r]||RCOL.common;
  if(st.m[r]) return st.m[r];
  c=document.createElement('canvas'); c.width=32; c.height=256; x=c.getContext('2d');
  x.fillStyle=col; x.fillRect(0,0,32,256);
  x.globalCompositeOperation='destination-in';
  gr=x.createLinearGradient(0,0,32,0);
  gr.addColorStop(0,'rgba(0,0,0,0)'); gr.addColorStop(0.3,'rgba(0,0,0,.35)'); gr.addColorStop(0.5,'rgba(0,0,0,1)'); gr.addColorStop(0.7,'rgba(0,0,0,.35)'); gr.addColorStop(1,'rgba(0,0,0,0)');
  x.fillStyle=gr; x.fillRect(0,0,32,256);
  gr=x.createLinearGradient(0,0,0,256);
  gr.addColorStop(0,'rgba(0,0,0,0)'); gr.addColorStop(0.55,'rgba(0,0,0,.45)'); gr.addColorStop(0.92,'rgba(0,0,0,1)'); gr.addColorStop(1,'rgba(0,0,0,.6)');
  x.fillStyle=gr; x.fillRect(0,0,32,256);
  st.m[r]=c; st.n++;
  return c;
}
function gfxBeamDraw(){
  var m=GFXE.wm, p=G.player, L=G.containers, i, ct, r, rk, Z=ZOOM(), n=0, pu;
  if(!m||!p||!L||!L.length) return 0;
  var vx0=VX-40, vy0=VY-40, vx1=VX+W/Z+40, vy1=VY+H/Z+200;
  for(i=0;i<L.length;i++){
    ct=L[i];
    if(ct.x<vx0||ct.x>vx1||ct.y<vy0||ct.y>vy1) continue;
    r=gfxKnownBest(ct); if(!r) continue;
    rk=_RRANK[r]||0; if(rk<2) continue;
    if(!canSee(p.x,p.y,p.face,ct.x,ct.y,G.vseg)) continue;
    if(!n){ wc.save(); wc.setTransform(m.a,m.b,m.c,m.d,m.e,m.f); wc.globalCompositeOperation='lighter'; }
    pu=0.5+0.5*Math.sin((G.t||0)*2.2+ct.x*0.03);
    wc.globalAlpha=(rk>=3?0.62:0.5)*(0.75+0.25*pu);
    wc.drawImage(gfxBeamSpr(r),ct.x-9,ct.y-150,18,154);
    n++;
  }
  if(n) wc.restore();
  return n;
}
// Batch E before the fog of war sheet: one call a drawn raid frame, in screen space (it sets the world transform itself).
function gfxPreFogE(dt){
  if(!gfxHook('prefogE')) return 0;
  var n=0;
  try{ n+=gfxBeamDraw(); }catch(_gbm){}
  return n;
}
// ===== GFX-E end =====

function gfxAir(dt){
  if(!gfxHook('air')) return 0;
  try{ GFXE.wm=wc.getTransform(); }catch(_gwm){ GFXE.wm=null; }   // v23.xx (gfx33): the world transform, for gfxPreFogE

