{v:'VER',what:'gfx33, his order 2026-10-12 (the graphics program, item 14): an elite pile the player can see sends up a beam, the same pile behind a wall does not, an uncommon pile never does, and an unopened elite box never does',
 run:function(){
   var bad=[], g=null, p, k, ek=null, uk=null, c=null, n, f0, i0, spr, sprU;
   var cnt=function(img){ var q=0, orig=wc.drawImage; wc.drawImage=function(im){ if(im===img) q++; return orig.apply(wc,arguments); }; try{ __frame(0.016); } finally { delete wc.drawImage; } return q; };
   var put=function(x,y,key,best,o){ var cc={x:x,y:y,r:15,type:'crate',d:-1,loot:[key],opened:false,time:0.6,best:best,rot:0,pulled:0}; for(var q in o) cc[q]=o[q]; G.containers.push(cc); return cc; };
   var drop=function(){ if(c){ var j=G.containers.indexOf(c); if(j>=0) G.containers.splice(j,1); c=null; } };
   try{
     if(!(window.__gfxStage&&window.__frame&&window.__state&&window.__endRaid)) return 'SKIP: this fixture has no gfx stage';
     g=__gfxStage({frames:2,cond:'night',x:1700,y:1290});
     if(!g) return 'SKIP: __gfxStage built no raid';
     if(g.sim) return 'SKIP: the staged raid is a sim raid';
     if(typeof gfxBeamSpr!=='function') return 'no loot beam: no gfxBeamSpr';
     GFX.bypass=0; G.shake=0; p=g.player; f0=p.face;
     for(k in ITEMS){ if(!ITEMS.hasOwnProperty(k)) continue; var it=ITEMS[k], r=dispR(k)||it.r; if(!ek&&r==='elite'&&it.use!=='ammo') ek=k; if(!uk&&r==='uncommon'&&it.use!=='ammo') uk=k; }
     if(!ek||!uk) return 'SKIP: no elite or no uncommon item to stage';
     spr=gfxBeamSpr('elite'); sprU=gfxBeamSpr('uncommon');
     p.face=0;
     if(!losClear(p.x,p.y,p.x+90,p.y,G.vseg)) return 'SKIP: a wall stands beside the staged spot';
     c=put(p.x+90,p.y,ek,'elite',{dropped:1});
     n=cnt(spr); if(n<1) bad.push('an elite pile in sight drew '+n+' beams');
     drop();
     c=put(p.x+90,p.y,uk,'uncommon',{dropped:1});
     n=cnt(sprU); if(n!==0) bad.push('an uncommon pile drew a beam');
     drop();
     c=put(p.x+90,p.y,ek,'elite',{});
     n=cnt(spr); if(n!==0) bad.push('an unopened elite box drew a beam');
     drop();
     p.face=Math.PI/2;
     if(losClear(p.x,p.y,p.x,p.y+180,G.vseg)) return 'SKIP: no racking wall south of the staged spot';
     c=put(p.x,p.y+180,ek,'elite',{dropped:1});
     n=cnt(spr); if(n!==0) bad.push('an elite pile behind a wall drew '+n+' beams');
     drop();
   }catch(e){ bad.push('threw: '+(e&&e.message||e)); }
   finally{
     try{ drop(); }catch(_dc){}
     try{ if(p) p.face=f0; }catch(_pf){}
     keys={};
     try{ var g2=__state(); if(g2&&!g2.over&&!g2.sim) __endRaid('abandon'); }catch(_e){}
     __topClear();
   }
   return bad.length?bad.join('; '):null; }},
